  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('i you:a ask:pr god beseech:imp that he to wesg',cases['1-9']['analysis'])
  self.assertIn('one_num god wesg:a',cases['2-10']['analysis'])
  self.assertIn('remainder of spirit',cases['2-15']['analysis'])
  self.assertIn('ipl mypl/messenger',cases['3-1']['analysis'])
  self.assertIn('he away put:ev hate:pr',cases['2-16']['analysis'])
  self.assertEqual({r for r,c in cases.items() if ':du' in c['analysis']},set())
  self.assertEqual(lang.lexicon['kjv_sun_righteousness']['form'],lang.lexicon['sun']['form'])
  self.assertEqual(lang.word('kjv_sun_righteousness')[0],lang.maxima(lang.lexicon['sun']['form']))
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),4)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
